import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Snackbar,
  Alert,
  SelectChangeEvent,
  Paper,
  Divider,
  Stack,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import { agentService } from '../services/api';

interface Agent {
  id: string;
  name: string;
  description?: string;
  parameters?: AgentParameter[];
}

interface AgentParameter {
  name: string;
  type: string;
  required: boolean;
  description?: string;
}

interface AgentExecution {
  agentId: string;
  parameters: Record<string, any>;
}

const AgentComponent: React.FC = () => {
  const [agents, setAgents] = useState<Agent[]>([]);
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [paramValues, setParamValues] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(false);
  const [loadingAgents, setLoadingAgents] = useState(true);
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    fetchAgents();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchAgents = async () => {
    setLoadingAgents(true);
    try {
      const agentsData = await agentService.getAgents();
      setAgents(agentsData);
      if (agentsData.length > 0) {
        setSelectedAgent(agentsData[0]);
        initializeParamValues(agentsData[0]);
      }
    } catch (error) {
      console.error('Failed to fetch agents:', error);
      setError('Failed to load agents. Please try again later.');
    } finally {
      setLoadingAgents(false);
    }
  };

  const handleAgentChange = (event: SelectChangeEvent) => {
    const agentId = event.target.value;
    const agent = agents.find(a => a.id === agentId) || null;
    setSelectedAgent(agent);
    if (agent) {
      initializeParamValues(agent);
    }
    setResult(null);
  };

  const initializeParamValues = (agent: Agent) => {
    const initialValues: Record<string, any> = {};
    if (agent.parameters) {
      agent.parameters.forEach(param => {
        initialValues[param.name] = '';
      });
    }
    setParamValues(initialValues);
  };

  const handleParamChange = (paramName: string, value: any) => {
    setParamValues(prev => ({
      ...prev,
      [paramName]: value
    }));
  };

  const executeAgent = async () => {
    if (!selectedAgent) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const execution: AgentExecution = {
        agentId: selectedAgent.id,
        parameters: paramValues
      };

      const response = await agentService.executeAgent(selectedAgent.id, execution);
      setResult(response);
    } catch (error) {
      console.error('Error executing agent:', error);
      setError('Failed to execute agent. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const closeError = () => {
    setError(null);
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h5" gutterBottom fontWeight="medium">
        Agent Playground
      </Typography>
      
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1fr 2fr' }, gap: 3 }}>
        {/* Agent Selection */}
        <Box>
          <Card elevation={2}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Select Agent
              </Typography>
              
              {loadingAgents ? (
                <Box display="flex" justifyContent="center" my={4}>
                  <CircularProgress size={30} />
                </Box>
              ) : (
                <FormControl fullWidth sx={{ mt: 2 }}>
                  <InputLabel id="agent-select-label">Agent</InputLabel>
                  <Select
                    labelId="agent-select-label"
                    id="agent-select"
                    value={selectedAgent?.id || ''}
                    onChange={handleAgentChange}
                    label="Agent"
                  >
                    {agents.map((agent) => (
                      <MenuItem key={agent.id} value={agent.id}>
                        {agent.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              )}
              
              {selectedAgent && (
                <Box mt={3}>
                  <Typography variant="body2" color="text.secondary">
                    {selectedAgent.description || 'No description available for this agent.'}
                  </Typography>
                </Box>
              )}
              
              <Box mt={3}>
                <Button
                  variant="outlined"
                  startIcon={<AddIcon />}
                  fullWidth
                  sx={{ mt: 1 }}
                >
                  Add New Agent
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Box>
        
        {/* Agent Parameters */}
        <Box>
          <Card elevation={2}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Configure Agent Parameters
              </Typography>
              
              {selectedAgent && selectedAgent.parameters && selectedAgent.parameters.length > 0 ? (
                <Box mt={2}>
                  <Stack spacing={2}>
                    {selectedAgent.parameters.map((param) => (
                      <TextField
                        key={param.name}
                        fullWidth
                        label={`${param.name}${param.required ? ' *' : ''}`}
                        value={paramValues[param.name] || ''}
                        onChange={(e) => handleParamChange(param.name, e.target.value)}
                        helperText={param.description}
                        variant="outlined"
                        size="small"
                      />
                    ))}
                  </Stack>
                  
                  <Box mt={3} display="flex" justifyContent="flex-end">
                    <Button
                      variant="contained"
                      color="primary"
                      startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />}
                      onClick={executeAgent}
                      disabled={loading}
                    >
                      {loading ? 'Executing...' : 'Execute Agent'}
                    </Button>
                  </Box>
                </Box>
              ) : (
                <Box py={4} textAlign="center">
                  <Typography variant="body1" color="text.secondary">
                    {selectedAgent 
                      ? 'This agent does not require any parameters.' 
                      : 'Please select an agent to configure parameters.'}
                  </Typography>
                  
                  {selectedAgent && (
                    <Box mt={3} display="flex" justifyContent="flex-end">
                      <Button
                        variant="contained"
                        color="primary"
                        startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />}
                        onClick={executeAgent}
                        disabled={loading}
                      >
                        {loading ? 'Executing...' : 'Execute Agent'}
                      </Button>
                    </Box>
                  )}
                </Box>
              )}
            </CardContent>
          </Card>
          
          {/* Results Section */}
          {result && (
            <Paper elevation={2} sx={{ mt: 3, p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Execution Results
              </Typography>
              <Divider sx={{ mb: 2 }} />
              <Box sx={{ 
                maxHeight: '300px', 
                overflow: 'auto',
                backgroundColor: '#f5f5f5',
                p: 2,
                borderRadius: 1,
                fontFamily: 'monospace'
              }}>
                <pre style={{ margin: 0, whiteSpace: 'pre-wrap' }}>
                  {JSON.stringify(result, null, 2)}
                </pre>
              </Box>
            </Paper>
          )}
        </Box>
      </Box>
      
      <Snackbar open={!!error} autoHideDuration={6000} onClose={closeError}>
        <Alert onClose={closeError} severity="error" sx={{ width: '100%' }}>
          {error}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default AgentComponent;
