import React from 'react';
import { 
  AppBar, 
  Toolbar, 
  Typography, 
  Box
} from '@mui/material';

const Header: React.FC = () => {
  return (
    <AppBar position="static" elevation={0}>
      <Toolbar>
        <Box display="flex" alignItems="center">
          <Typography
            variant="h5"
            component="div"
            sx={{ 
              fontWeight: 700,
              letterSpacing: '0.5px',
            }}
          >
            agno_hub Hub
          </Typography>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Header;
